solution.solution.c:
struct rgb565 { unsigned blue : 5; unsigned green : 6; unsigned red : 5; };

struct rgb565 to_rgb565(int r, int g, int b)
{
    struct rgb565 c;
    c.red = (unsigned)r >> 3;
    c.green = (unsigned)g >> 2;
    c.blue = (unsigned)b >> 3;
    return c;
}

void from_rgb565(struct rgb565 c, int *r, int *g, int *b)
{
    *r = (int)((c.red << 3) | (c.red >> 2));
    *g = (int)((c.green << 2) | (c.green >> 4));
    *b = (int)((c.blue << 3) | (c.blue >> 2));
}

unitTests:
TEST("packing") { struct rgb565 c = to_rgb565(255, 128, 0); CHECK_EQ((int)c.red, 31); CHECK_EQ((int)c.green, 32); CHECK_EQ((int)c.blue, 0); struct rgb565 d = to_rgb565(7, 3, 8); CHECK_EQ((int)d.red, 0); CHECK_EQ((int)d.green, 0); CHECK_EQ((int)d.blue, 1); }
TEST("unpacking") { int r, g, b; from_rgb565(to_rgb565(255, 128, 0), &r, &g, &b); CHECK_EQ(r, 255); CHECK_EQ(g, 130); CHECK_EQ(b, 0); from_rgb565(to_rgb565(0, 255, 255), &r, &g, &b); CHECK_EQ(r, 0); CHECK_EQ(g, 255); CHECK_EQ(b, 255); }
TEST("small") { CHECK(sizeof(struct rgb565) <= 4); }

